/** One single byte code page: its identifier, and what a byte of it decodes to. */
export interface CodePageTable {
  /** A short label for the page, e.g. 'latin1'. */
  readonly id: string;
  /** The Microsoft code page identifier, e.g. 28591. */
  readonly codePage: number;
  /** What the page is called, e.g. 'ISO 8859-1'. */
  readonly name: string;
  /** Byte value to Unicode code point, 256 entries. */
  readonly toUnicode: readonly number[];
}

